const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='journey-context-demo-v1';
function freshState(){return {destination:'안목해변',destinationPlace:'p2',theme:'all',sourceState:'ready',navOutcome:'success',tripPhase:'planning',navigation:null,companion:'unknown',weather:'sun',driving:false,vehicleState:'park',category:'all',page:0,novel:false,route:[],visits:structuredClone(KB.initialVisits),profile:{...structuredClone(KB.initialProfile),likes:[]},view:'home',graphPlace:'p1',...freshVehicle(),first:freshFirst(),ai:freshAi(),aiOutcome:'ok',tripVoice:null};}
let state=freshState();
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.visits)&&Array.isArray(saved.route)&&saved.profile&&Array.isArray(saved.profile.preferences)){state={...state,...saved,first:{...freshFirst(),...(saved.first||{})},ai:{...freshAi(),...(saved.ai||{}),stage:'idle',reorder:null},profile:{likes:[],...saved.profile},destinationPlace:saved.destinationPlace??null,driving:false,vehicleState:'park',view:'home',navigation:null,tripPhase:'planning'};['leg1','leg2'].forEach(l=>{if(state.first[l]==='wait')state.first[l]='idle';});if(DRIVING_LEGS.includes(state.first.trip)){state.vehicleState='drive';state.driving=true;}}}catch(e){}
if(sceneFromHash())state=scenePreset(sceneFromHash());
let modalReturnFocus;let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){toast('이 환경에서는 저장이 어려워요. 현재 화면에서 계속 사용할 수 있어요.')}}
function guard(){if(!state.driving)return true;toast('주행 중에는 화면 조작을 잠시 쉬어요. 정차 후 이어가세요.');return false;}
function setCompanion(c){if(!guard())return;state.companion=c;state.page=0;aiReset();save();render();toast(c==='mom'?'어머니와 동행 예정으로 반영했어요. 실제 방문 동행은 따로 확인해요.':c==='solo'?'이번 여정은 혼자예요. 동행자 선호를 적용하지 않아요.':'이번 동행은 미정으로 두었어요.');}
function showModal(title,body){if(!$('#modal').open)modalReturnFocus=document.activeElement;$('#modalBody').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="닫기">×</button></div>${body}`;if(!$('#modal').open)$('#modal').show();$('#vehicleDisplay').classList.add('dialog-open');$('#modal').setAttribute('aria-modal','true');const focusable=$('#modal').querySelector('button,input,select,textarea');if(focusable)focusable.focus();}
function close(){if(state.navigation?.status==='pending'){state.navigation=null;navigationSerial++;}visitDraft=null;if(state.ai)state.ai.pending=null;$('#modal').classList.remove('sheet');$('#modal').close();$('#vehicleDisplay').classList.remove('dialog-open');if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function place(id){return KB.places.find(p=>p.id===id)}
const categories={food:'음식점',cafe:'카페',visit:'방문지'};
function art(p){return artSvg(p.art,p.name);}
